commands.command:
set -euo pipefail; grep -q "climateTab: 'Gniazdka'" apps/mobile/src/app/locales/pl.ts; grep -q "PlainPlugCard" apps/mobile/src/screens/AutomationDashboardScreen.tsx; git status --short; python3 - <<'PY'
from pathlib import Path

def rep(path, old, new, count=None):
    p=Path(path); text=p.read_text();
    if old not in text: raise SystemExit(f'missing {old!r} in {path}')
    p.write_text(text.replace(old,new) if count is None else text.replace(old,new,count))

# Dashboard tests: rename only the Plug-tab expectations and cover an unconfigured saved plug.
p='apps/mobile/src/__tests__/automation-dashboard.test.tsx'
text=Path(p).read_text()
text=text.replace("import { cleanup, fireEvent, render, screen, waitFor } from '@testing-library/react';", "import { cleanup, fireEvent, render, screen, waitFor, within } from '@testing-library/react';")
text=text.replace("import { AutomationDashboardScreen } from '../screens/AutomationDashboardScreen.js';", "import {
  resetHardwareSetupDraftStore,
  useHardwareSetupDraftStore
} from '../flows/hardware-setup/setupDraftStore.js';
import { AutomationDashboardScreen } from '../screens/AutomationDashboardScreen.js';")
text=text.replace("    resetInstalledAutomationStore();
    vi.restoreAllMocks();", "    resetInstalledAutomationStore();
    resetHardwareSetupDraftStore();
    vi.restoreAllMocks();")
text=text.replace("    resetInstalledAutomationStore();
    vi.unstubAllGlobals();", "    resetInstalledAutomationStore();
    resetHardwareSetupDraftStore();
    vi.unstubAllGlobals();")
text=text.replace("expect(screen.getByRole('heading', { name: 'Twoje automatyki' })).toBeVisible();", "expect(screen.getByRole('heading', { name: 'Gniazdka' })).toBeVisible();", 1)
text=text.replace("name: 'Klimat'", "name: 'Gniazdka'")
needle="  it('shows live runtime values from Shelly for a saved installation', async () => {"
new_test="  it('shows a saved plug without automation and starts setup with that plug context', () => {
    const onAddAutomation = vi.fn();
    useHardwareSetupDraftStore.getState().upsertShellyDevice({
      id: 'http://192.168.0.30/',
      name: 'Nawilżacz',
      baseUrl: 'http://192.168.0.30/',
      scriptIdInput: '1'
    });

    renderDashboard(onAddAutomation);

    const card = screen.getByText('Nawilżacz').closest('article');
    expect(card).not.toBeNull();
    expect(within(card as HTMLElement).getByText('Brak automatyzacji')).toBeVisible();
    fireEvent.click(
      within(card as HTMLElement).getByRole('button', { name: 'Dodaj automatykę' })
    );
    expect(onAddAutomation).toHaveBeenCalledWith('climate', 'http://192.168.0.30/');
  });

"+needle
if needle not in text: raise SystemExit('dashboard insertion point missing')
text=text.replace(needle,new_test,1)
Path(p).write_text(text)

