text=text.replace("expect(screen.getByRole('heading', { name: 'Twoje automatyki' })).toBeVisible();
    expect(screen.getByRole('button', { name: 'Dodaj automatykę' })).toBeVisible();
    expect(screen.getByRole('button', { name: 'Klimat' }))", "expect(screen.getByRole('heading', { name: 'Gniazdka' })).toBeVisible();
