needle="  it('opens time setup directly from the Time plus and returns to Time dashboard', async () => {"
new_test="  it('starts climate setup from a saved plug without asking for the plug again', async () => {
    useHardwareSetupDraftStore.getState().upsertShellyDevice({
      id: 'http://192.168.0.30/',
      name: 'Nawilżacz',
      baseUrl: 'http://192.168.0.30/',
      scriptIdInput: '1'
    });
    renderRoutes();

    const card = screen.getByText('Nawilżacz').closest('article');
    expect(card).not.toBeNull();
